void Solver::rephase() {
    rephases = 0;
    threshold *= 0.95;
    rephase_limit += 4096;

    // Update saved phases based on current trail assignments
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {
            // Prefer the current assignment if variable is assigned
            saved[i] = value[i];
        } else if (rand() % 100 < 30) {
            // Occasionally randomize unassigned variables
            saved[i] = rand() % 2 ? 1 : -1;
        }
        // Otherwise keep existing saved value
    }
}
